mat2 obtenirMatriceRotation(float angle) {
    return mat2(
        cos(angle), -sin(angle),
        sin(angle),  cos(angle)
    );
}

float genererBruitAleatoire(vec3 position) {
    return fract(sin(dot(position, vec3(12.989, 78.233, 45.164))) * 43758.545);
}

float calculerVagueBase(vec3 position) {
    float temps = iTime;
    return sin(position.x * 0.3 + temps) * cos(position.z * 0.25 - temps * 0.8) * 1.2;
}

float calculerBruitFractal3D(vec3 position, float frequenceInitiale, float multiplicateurFrequence, float modeInterpolation) {
    float temps = iTime;
    float valeurAccumulee = 0.0;
    float amplitude = 0.2;
    vec3 positionCourante = position;
    float frequence = frequenceInitiale;

    for (int octave = 0; octave < 7; octave++) {
        vec3 positionOndulee = positionCourante * frequence + sin(positionCourante.xzx * 0.4 + temps * 1.5);
        vec3 indexGrille = floor(positionOndulee);
        vec3 fractionGrille = fract(positionOndulee);

        fractionGrille = fractionGrille * fractionGrille * (3.0 - 2.0 * fractionGrille);

        float coin000 = genererBruitAleatoire(indexGrille);
        float coin100 = genererBruitAleatoire(indexGrille + vec3(1.0, 0.0, 0.0));
        float coin010 = genererBruitAleatoire(indexGrille + vec3(0.0, 1.0, 0.0));
        float coin110 = genererBruitAleatoire(indexGrille + vec3(1.0, 1.0, 0.0));

        float coin001 = genererBruitAleatoire(indexGrille + vec3(0.0, 0.0, 1.0));
        float coin101 = genererBruitAleatoire(indexGrille + vec3(1.0, 0.0, 1.0));
        float coin011 = genererBruitAleatoire(indexGrille + vec3(0.0, 1.0, 1.0));
        float coin111 = genererBruitAleatoire(indexGrille + vec3(1.0, 1.0, 1.0));

        float melangeX0 = mix(coin000, coin100, fractionGrille.x);
        float melangeX1 = mix(coin010, coin110, fractionGrille.x);
        float melangeY0 = mix(melangeX0, melangeX1, fractionGrille.y);

        float melangeX2 = mix(coin001, coin101, fractionGrille.x);
        float melangeX3 = mix(coin011, coin111, fractionGrille.x);
        float melangeY1 = mix(melangeX2, melangeX3, fractionGrille.y);

        float interpolationZ = (modeInterpolation > 0.0) ? indexGrille.z : fractionGrille.z;
        valeurAccumulee += amplitude * mix(melangeY0, melangeY1, interpolationZ);

        positionCourante.xy *= obtenirMatriceRotation(0.4);
        positionCourante.yz *= obtenirMatriceRotation(0.3);
        frequence *= multiplicateurFrequence;
        amplitude *= 0.45;
    }

    return valeurAccumulee;
}

float estimerDistanceOcean(vec3 position) {
    float temps = iTime;
    vec3 positionDecalee = position * 0.45 + vec3(0.0, 0.0, temps * 0.3);
    float hauteurBruit = (calculerBruitFractal3D(positionDecalee, 1.0, 2.7, 0.0) + 1.0) * 4.5;
    float hauteurVague = calculerVagueBase(position);

    return position.y + 1.2 - hauteurBruit - hauteurVague;
}

float calculerHauteurEchantillon(vec3 position, vec3 decalage, float hauteurBruitBase) {
    vec3 positionEchantillonee = position + decalage;
    return positionEchantillonee.y + 1.2 - hauteurBruitBase - calculerVagueBase(positionEchantillonee);
}

void mainImage(out vec4 couleurFragment, vec2 coordFragment) {
    float temps = iTime;
    vec3 resolution = iResolution;

    vec2 uvNormalisees = (coordFragment - 0.4 * resolution.xy) / resolution.y;

    vec3 origineRayon = vec3(0.0, 5.5, 18.0);
    origineRayon.xz *= obtenirMatriceRotation(temps * 0.04);

    vec3 directionCible = normalize(vec3(0.0, 4.2, 0.0) - origineRayon);
    vec3 axeHorizontalCam = normalize(cross(directionCible, vec3(0.0, 1.0, 0.0)));
    vec3 axeVerticalCam = cross(axeHorizontalCam, directionCible);
    vec3 directionRayon = normalize(uvNormalisees.x * axeHorizontalCam + uvNormalisees.y * axeVerticalCam + 1.6 * directionCible);

    vec3 couleurFinale = vec3(0.0);
    float distanceMarching = 0.0;
    float distanceScene = 0.0;
    float luminescenceAccumulee = 0.0;

    for (int etape = 0; etape < 160; etape++) {
        vec3 positionCourante = origineRayon + directionRayon * distanceMarching;
        distanceScene = estimerDistanceOcean(positionCourante);

        luminescenceAccumulee += exp(-max(distanceScene, 0.0) * 9.6) * 0.42;

        if (abs(distanceScene) < 0.001 * distanceMarching || distanceMarching > 101.8) break;

        distanceMarching += distanceScene * 0.55;
    }

    if (distanceMarching < 40.0) {
        vec3 positionImpact = origineRayon + directionRayon * distanceMarching;
        float hauteurBruitBase = calculerBruitFractal3D(vec3(0.0, 0.0, temps * 0.3), 0.0, 2.35, 0.0) * 4.5;

        float epsilon = 0.003;
        float hDX = calculerHauteurEchantillon(positionImpact, vec3(epsilon, 0.0, 0.0), hauteurBruitBase) - calculerHauteurEchantillon(positionImpact, vec3(-epsilon, 0.0, 0.0), hauteurBruitBase);
        float hDY = calculerHauteurEchantillon(positionImpact, vec3(0.0, epsilon, 0.0), hauteurBruitBase) - calculerHauteurEchantillon(positionImpact, vec3(0.0, -epsilon, 0.0), hauteurBruitBase);
        float hDZ = calculerHauteurEchantillon(positionImpact, vec3(0.0, 0.0, epsilon), hauteurBruitBase) - calculerHauteurEchantillon(positionImpact, vec3(0.0, 0.0, -epsilon), hauteurBruitBase);

        vec3 normaleSurface = normalize(vec3(hDX, hDY, hDZ));

        vec3 directionLumiere = normalize(vec3(1.5, 2.5, -1.0));
        vec3 directionReflet = reflect(directionLumiere, normaleSurface);

        float speculaire = pow(max(dot(directionReflet, directionRayon), 0.0), 32.0);
        float attenuationBrouillard = exp(-0.015 * distanceMarching * distanceMarching);

        couleurFinale = speculaire * vec3(1.0, 0.9, 0.7) * 0.8 * attenuationBrouillard;
    } else {
        vec3 directionCiel = directionRayon;
        directionCiel.yz *= obtenirMatriceRotation(sin(temps * 0.05) * 0.1);
        directionCiel.xz *= obtenirMatriceRotation(temps * 0.01);

        for (float couche = 1.0; couche < 15.0; couche += 1.0) {
            vec3 positionEtoile = directionCiel * (25.0 + couche * 22.0);
            float valeurAleatoireEtoile = genererBruitAleatoire(floor(positionEtoile));

            float clignotement = sin(temps * 4.0 * valeurAleatoireEtoile + valeurAleatoireEtoile * 30.0) * 0.5 + 0.5;
            float formeEtoile = smoothstep(0.2, 0.0, length(fract(positionEtoile) - 0.5) - 0.002 * couche);

            couleurFinale += clignotement * vec3(1.0, 0.7, 0.4) * formeEtoile * 4.0;
        }
    }

    couleurFinale += vec3(1.0, 0.25, 0.01) * luminescenceAccumulee * 1.3 + vec3(1.0, 0.6, 0.1) * pow(luminescenceAccumulee, 2.2) * 0.5;

    vec3 couleurAjustee = clamp(couleurFinale * (2.51 * couleurFinale + 0.03) / (couleurFinale * (2.43 * couleurFinale + 0.59) + 0.14), 0.0, 1.0);

    couleurFragment = vec4(couleurAjustee, 1.0);
}
